import sys

def main():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        x = int(line)
    except ValueError:
        return

    if x == 1:
        print("-1")
        return

    found = False
    for a in range(1, x + 1):
        for b in range(1, a + 1):
            if a % b == 0:
                if a * b > x and a // b < x:
                    if 1 <= b <= x:
                        print(f"{a} {b}")
                        found = True
                        break
        if found:
            break

    if not found:
        print("-1")

if __name__ == "__main__":
    main()
